head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF05702.xml";
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vIsurCd = "";
scwin.trsIdx; // insert, update 구분
scwin.rowPos;
scwin.vISU_ENG_NM = "";
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID());
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.listCount = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    //arrPar[1] = getObjectValue(txb_SearchNm);	// 명칭값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/*
 * 종목코드 선택시 
 */
scwin.fn_SetParIsuCd = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        scwin.fn_initItem();
        scwin.fn_list_sync(); //행사가격 조정내역
        scwin.fn_bfprc(); //변경전 행사가격

    }
};
scwin.fn_initItem = function() {
    buttonSet.setInsertStatus();
    dts_Isu.removeAll();
    dts_Isu.insertRow();
    dts_Mst.removeAll();
    dts_Mst.insertRow();
    scwin.vBzProcsNo = ""; //초기화 

};


//종목코드 선택시 변경전 행사가격을 가져온다.
scwin.fn_bfprc = function() {
    var url = "/Listing.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchSWPrclist&inputMessageId=CHGLIST_PRC_INOUT&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
};



//종목코드선택시 행사가격 조정 내역 조회
scwin.fn_list_sync = function() {
    var url = "/Listing.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchChgList&DIV_IDX=10&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
scwin.fn_getListBzTpCd = function() {
    var VListBzTpCd = "";
    if (scwin.fr_SecuGrpId == SECUGRP_ID_SW) {
        //SW : 신주인수권증권
        VListBzTpCd = LIST_BZ_TP_CD_150; //상장업무구분코드 : 150 - 신주인수권증권 행사가격

    }
    return VListBzTpCd;
};



//그리드  더블 클릭시 조회
scwin.fn_read_sync = function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    var url = "/Listing.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchChgList&DIV_IDX=12&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목코드]를 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_CHG_DD) == "") {
        $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if ($c.ut.cGetToday("yyyymmdd") >= $c.stf.getObjectValue(edt_CHG_DD)) {
        $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_CHG_RSN_CONTN) == "") {
        $c.win.alert("[변경사유]을 입력하세요.");
        txb_CHG_RSN_CONTN.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_CHG_RSN_CONTN, 1000, "변경사유")) return false;
    if ($c.stf.getObjectValue(edt_AFCHG_EXER_PRC) == "") {
        $c.win.alert("[변경후 행사가격(원)]을 입력하세요.");
        edt_AFCHG_EXER_PRC.focus();
        return false;
    }
    if (!$c.lc.fn_check_bz_doubleinput(dts_BZ_CHECK, $c.stf.getObjectValue(txb_ISU_CD), $c.stf.getObjectValue(edt_CHG_DD), dts_Mst.getCellData(1, "BZ_PROCS_NO"), scwin.fn_getListBzTpCd())) {
        return false;
    }
    return true;
};



//저장
scwin.fn_save = function() {
    scwin.trsIdx = TRS_IDX_INSERT;
    if (!scwin.fn_CheckForm()) return;
    if (!$c.lc.fn_isProcess('I')) return;
    scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        //alert('[dts_Mst]'+dts_Mst.text);
        scwin.fn_trs();
    }
};
scwin.fn_update = function() {
    scwin.trsIdx = TRS_IDX_UPDATE;
    if (!scwin.fn_CheckForm()) return;
    if (!$c.lc.fn_isProcess('U')) return;
    scwin.fn_trs();
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_trs();
};
scwin.fn_trs = function() {
    if (scwin.trsIdx == '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.trsIdx == '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.trsIdx == '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    dts_Mst.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
    dts_Mst.setCellData(1, "ISU_CD", $c.stf.getObjectValue(txb_ISU_CD));
    dts_Mst.setCellData(1, "BFCHG_EXER_PRC", edt_BFCHG_EXER_PRC.getValue());
    dts_Mst.setCellData(1, "AFCHG_EXER_PRC", edt_AFCHG_EXER_PRC.getValue());
    trs_Save.Action = $c.lc.fn_encodeNSession("/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveChgList");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I: dtsParm1= dts_Mst )";
    trs_Save.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",COUNT=1" + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_150 + ",DIV_IDX[0]=" + DIV_IDX_CHGLIST_SWPRC;
    trs_Save.Post();
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return;
    } else {
        scwin.fn_initItem();
        scwin.fn_bfprc();
        scwin.fn_list_sync();
    }
};
scwin.img_ISU_NM_onclick = function() {
    fn_GetPar = fn_GetParIsuCd;
    fn_SetPar = fn_SetParIsuCd;
    $c.lc.fn_PopFindIsu(scwin.fr_SecuGrpId);
};
scwin.img_CHD_DD_onclick = function() {
    popUpCalendar2(edt_CHG_DD);
};
scwin.dts_BZ_CHECK_OnLoadError = function() {
    $c.stf.alert_error(dts_BZ_CHECK);
};
scwin.dts_Mst_OnLoadError = function() {
    $c.stf.alert_error(dts_Mst);
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
    } else {
        if ($c.ut.cGetToday("yyyymmdd") < $c.stf.getObjectValue(edt_CHG_DD)) {
            buttonSet.setUpdateStatus();
        } else {
            buttonSet.setErrorStatus();
        }
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
    }
};
scwin.grd_List_OnClick = function(row, colid) {
    scwin.fn_read_sync(row);
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_initItem();
    scwin.fn_list_sync();
    scwin.fn_bfprc();
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_New_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return;
    } else {
        scwin.fn_initItem();
        scwin.fn_bfprc();
        scwin.fn_list_sync();
    }
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    $c.libRoundPanel.PanelToGroupBox(panel_Item);

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제


    buttonSet.setInsertStatus();
    dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELISTING_ISU_INOUT";
    dts_Isu.reset();
};
